        printf("%02x", bytes->bytes[i]);
    }
    printf("\n");
}

/**
 * Print a Bytes48 to the console.
 *
 * @param[in]   bytes   The Bytes48 to print
 */
void print_bytes48(const Bytes48 *bytes) {
    for (size_t i = 0; i < 48; i++) {
        printf("%02x", bytes->bytes[i]);
    }
    printf("\n");
}

